@dataclass(frozen=True)
class WorkflowRoutingInfo:
    """Transparent record of how a chat turn was routed.

    JVNAUTOSCI-825: Provides traceable reasoning for the routing decision:
    which workflow was selected, what the classifier verdict was, which
    discovered workflows were candidates, and how long routing took.

    JVNAUTOSCI-1424 Phase 3: Enriched with confidence_score and reasoning
    from the model-based selection.
    """

    workflow_id: str
    verdict: str
    prompt_id: str | None
    discovered_workflow_ids: tuple[str, ...]
    routing_duration_ms: float | None = None
    source: str = (
        "selector"  # "selector" | "selector_override" | "default" | "presenter_mode"
    )
    confidence_score: float = 0.0
    reasoning: str = ""
    selection_rationale: str = ""


def _resolve_identity_context(
    *,
    user_concept_id: str | None,
    org_concept_id: str | None,
    user_namespace: str | None,
) -> tuple[str | None, str | None]:
    """Resolve actor IDs from explicit inputs first, then canonical namespace components."""

    resolved_user = user_concept_id if isinstance(user_concept_id, str) else None
    resolved_org = org_concept_id if isinstance(org_concept_id, str) else None
    namespace_user, namespace_org = derive_actor_context_from_namespace(user_namespace)
    if not resolved_user:
        resolved_user = namespace_user
    if not resolved_org:
        resolved_org = namespace_org
    return resolved_user, resolved_org


def _coerce_conversation_turn_llm_timeout_override_sec(
    raw_timeout: Any,
) -> float | None:
    return coerce_conversation_turn_llm_timeout_sec(raw_timeout)


def _default_conversation_turn_llm_timeout_override_sec() -> float | None:
    return default_conversation_turn_llm_timeout_sec(
        os.getenv("VON_CONVERSATION_TURN_LLM_TIMEOUT_SEC")
    )


def _conversation_turn_llm_timeout_override_sec_from_data(
    data: Mapping[str, Any] | None,
) -> float | None:
    if not isinstance(data, Mapping):
        return None
    return _coerce_conversation_turn_llm_timeout_override_sec(
        data.get(_CONVERSATION_TURN_LLM_TIMEOUT_CONTEXT_KEY)
    )


@dataclass(frozen=True)
class OrchestratorResult:
    """Structured response from a tool-aware chat exchange."""

    response_text: str
