@dataclass(frozen=True)
class _PromptRequirementEvaluation:
    """Canonical prompt-requirement snapshot shared across routing/execution."""

    required_tools: tuple[str, ...] = ()
    required_url_extraction_tool: str | None = None
    required_url_extraction_url: str | None = None
    required_fetch_concept_ids: tuple[str, ...] = ()
    required_read_file_copy_ids: tuple[str, ...] = ()
    required_scholarly_representation_file_copy_ids: tuple[str, ...] = ()
    required_create_type_name: str | None = None
    unavailable_required_tools: tuple[str, ...] = ()
    # DEPRECATED: Always False — scholarly representation intent is now
    # workflow/LLM-owned.  Kept for structural compatibility.
    scholarly_representation_intent: bool = False
    missing_tools: tuple[str, ...] = ()
    missing_fetch_concept_ids: tuple[str, ...] = ()
    missing_read_file_copy_ids: tuple[str, ...] = ()
    missing_scholarly_representation_file_copy_ids: tuple[str, ...] = ()
    missing_retry_reason: str | None = None

    @property
    def has_missing_requirements(self) -> bool:
        return bool(
            self.missing_tools
            or self.missing_fetch_concept_ids
            or self.missing_read_file_copy_ids
            or self.missing_scholarly_representation_file_copy_ids
        )


_WORKFLOW_EXECUTION_SUMMARY_SCHEMA_VERSION = "workflow_execution_summary.v1"
_WORKFLOW_EXECUTION_SUMMARY_MAX_TERMINAL_EFFECTS = 20
_WORKFLOW_EXECUTION_SUMMARY_MAX_SIDE_EFFECTS = 24
_WORKFLOW_EXECUTION_SUMMARY_MAX_IDS_PER_EFFECT = 50
_WORKFLOW_EXECUTION_SUMMARY_MAX_SCAN_DEPTH = 3
_WORKFLOW_EXECUTION_SUMMARY_IGNORED_KEYS: frozenset[str] = frozenset(
    {
        "aux_llm_calls",
        "extra_messages",
        "llm_calls",
        "tool_invocations",
        "turn_execution_diagnostics",
        "turn_execution_record",
        "workflow_execution_summary",
        "workflow_result_envelope",
        "workflow_step_result_envelopes",
        "workflow_terminal_effect_events",
        "workflow_control_flow_events",
    }
)
_WORKFLOW_EXECUTION_AUX_RESULT_SNAPSHOT_KEYS: tuple[str, ...] = (
    "run_id",
    "experiment_spec_id",
    "theory_id",
    "verdict",
    "verdict_summary",
    "promotion_recommendation",
    "observations",
    "metadata_verification",
    "cleanup_summary",
    "cleanup_passed",
    "verification_passed",
    "workflow_execution",
    "target_workflow_execution",
    "paper_concept_id",
    "file_copy_concept_id",
    "learning_signal",
)
_WORKFLOW_EXECUTION_AUX_RESULT_SNAPSHOT_FALLBACK_KEYS: dict[str, tuple[str, ...]] = {
    # Older and workflow-family-specific result payloads may expose evidence
    # under a specialised key. Preserve a canonical `observations` field in the
    # aux snapshot so downstream telemetry checks do not need workflow-specific
    # branching.
    "observations": ("meeting_candidate_observations",),
}
_WORKFLOW_MUTATION_ID_FIELD_PATTERN = re.compile(
    r"^(created|updated|upserted|materialised|materialized|deleted|removed|linked|bound|scheduled|promoted|merged)_(.+?)_ids?$",
    flags=re.IGNORECASE,
)
_WORKFLOW_FAILURE_LIKE_FINAL_STATE_TOKENS = (
    "_failed",
    "failed",
    "_error",
    "error",
    "_invalid",
    "invalid",
    "_rejected",
    "rejected",
    "_cancelled",
    "cancelled",
)


def _workflow_execution_summary_text(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    cleaned = value.strip()
    return cleaned or None


def _workflow_final_state_is_failure_like(final_state: str | None) -> bool:
    lowered_final_state = (final_state or "").lower()
    if not lowered_final_state:
        return False
    return any(
        token in lowered_final_state
        for token in _WORKFLOW_FAILURE_LIKE_FINAL_STATE_TOKENS
    )


def _workflow_completion_gate_summary(workflow_result: Any) -> dict[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None
    gate_raw = result_data.get(WORKFLOW_COMPLETION_GATE_KEY)
    gate = gate_raw if isinstance(gate_raw, Mapping) else {}
    if not gate:
        return None
    blocking_reason_codes = [
        _workflow_execution_summary_text(item)
        for item in gate.get("blocking_reason_codes") or []
        if _workflow_execution_summary_text(item)
    ]
    return {
        "safe_to_claim_completion": bool(gate.get("safe_to_claim_completion", False)),
        "blocking_reason_codes": list(blocking_reason_codes),
    }


def _workflow_terminal_success_contract_from_result(
    workflow_result: Any,
) -> Mapping[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None
    contract = result_data.get("workflow_terminal_success_contract")
    if isinstance(contract, Mapping):
        return contract
    return None


def _workflow_required_effects_contract_from_result(
    workflow_result: Any,
) -> Mapping[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None
    contract = result_data.get("workflow_required_effects_contract")
    if isinstance(contract, Mapping):
        return contract
    return None


def _workflow_required_effects_contract_source_from_result(
    workflow_result: Any,
) -> str | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None
    source = result_data.get("workflow_required_effects_contract_source")
    if isinstance(source, str) and source.strip():
        return source.strip()
    return None


def _workflow_required_tools_from_contract(
    contract: Mapping[str, Any] | None,
) -> list[str]:
    if not isinstance(contract, Mapping):
        return []
    required_effects = contract.get("required_effects")
    if not isinstance(required_effects, Sequence) or isinstance(
        required_effects, (str, bytes, bytearray)
    ):
        return []
    tools: list[str] = []
    seen: set[str] = set()
    for effect in required_effects:
        if not isinstance(effect, Mapping):
            continue
        raw_tools = effect.get("required_tools")
        if not isinstance(raw_tools, Sequence) or isinstance(
            raw_tools, (str, bytes, bytearray)
        ):
            continue
        for raw_tool in raw_tools:
            if not isinstance(raw_tool, str):
                continue
            tool = raw_tool.strip()
            if not tool:
                continue
            lowered = tool.lower()
            if lowered in seen:
                continue
            seen.add(lowered)
            tools.append(tool)
    return tools


def _normalise_tool_name_sequence(value: Any) -> list[str]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
        return []
    tools: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, str):
            continue
        tool = item.strip()
        if not tool:
            continue
        lowered = tool.lower()
        if lowered in seen:
            continue
        seen.add(lowered)
        tools.append(tool)
    return tools


def _llm_policy_enables_tool_surface(llm_policy: Mapping[str, Any]) -> bool:
    raw_mode = str(llm_policy.get("tool_mode") or "").strip().lower()
    if raw_mode in {"none", "disabled", "off"}:
        return False
    if raw_mode in {"allowed", "tool_augmented", "tools"}:
        return True
    return "allowed_tools" in llm_policy or "required_tools" in llm_policy


def _evaluate_workflow_required_effects_tool_policy(
    workflow_def: Any | None,
) -> dict[str, Any]:
    metadata = (
        getattr(workflow_def, "metadata", None) if workflow_def is not None else None
    )
    contract = (
        metadata.get("required_effects_contract")
        if isinstance(metadata, Mapping)
        else None
    )
    required_tools = _workflow_required_tools_from_contract(
        contract if isinstance(contract, Mapping) else None
    )
    if not required_tools:
        return {
            "checked": False,
            "ok": True,
            "required_tools": [],
            "allowed_tools": [],
            "unavailable_required_tools": [],
            "reason_code": "no_required_effect_tools",
        }

    allowed_tools: set[str] = set()
    direct_action_tools: set[str] = set()
    has_unrestricted_llm_tool_step = False
    unrestricted_tool_pipeline_actions: set[str] = set()
    states = getattr(workflow_def, "states", None)
    if isinstance(states, Mapping):
        for state in states.values():
            actions = getattr(state, "actions", None)
            if not isinstance(actions, Sequence) or isinstance(actions, str):
                continue
            for action in actions:
                action_id = getattr(action, "action_id", None)
                if isinstance(action_id, str) and action_id.strip():
                    cleaned_action_id = action_id.strip().lower()
                    direct_action_tools.add(cleaned_action_id)
                    if (
                        cleaned_action_id
                        in _REQUIRED_EFFECTS_UNRESTRICTED_TOOL_SURFACE_ACTION_IDS
                    ):
                        unrestricted_tool_pipeline_actions.add(cleaned_action_id)
                if not bool(getattr(action, "is_llm_step", False)):
                    continue
                llm_policy = getattr(action, "llm_policy", None)
                llm_policy_map = llm_policy if isinstance(llm_policy, Mapping) else {}
                if not _llm_policy_enables_tool_surface(llm_policy_map):
                    continue
                allowed = _normalise_tool_name_sequence(
                    llm_policy_map.get("allowed_tools")
                )
                if allowed:
                    allowed_tools.update(tool.lower() for tool in allowed)
                else:
                    has_unrestricted_llm_tool_step = True

    has_unrestricted_tool_pipeline_step = bool(unrestricted_tool_pipeline_actions)
    if has_unrestricted_llm_tool_step or has_unrestricted_tool_pipeline_step:
        unavailable_required_tools: list[str] = []
    else:
        available_lower = set(allowed_tools)
        available_lower.update(direct_action_tools)
        unavailable_required_tools = [
            tool for tool in required_tools if tool.lower() not in available_lower
        ]

    ok = not unavailable_required_tools
    return {
        "checked": True,
        "ok": ok,
        "required_tools": list(required_tools),
        "allowed_tools": sorted(allowed_tools),
        "direct_action_tools": sorted(direct_action_tools),
        "unrestricted_llm_tool_step": bool(has_unrestricted_llm_tool_step),
        "unrestricted_tool_pipeline_step": has_unrestricted_tool_pipeline_step,
        "unrestricted_tool_pipeline_actions": sorted(
            unrestricted_tool_pipeline_actions
        ),
        "unavailable_required_tools": list(unavailable_required_tools),
        "reason_code": ("ok" if ok else "workflow_required_effect_tool_not_allowed"),
    }


def _workflow_selection_outcome_safe_int(value: Any) -> int:
    try:
        return int(value)
    except Exception:
        return 0


def _workflow_selection_outcome_safe_float(value: Any) -> float | None:
    try:
        return float(value)
    except Exception:
        return None


def _workflow_selection_tool_invocation_names(
    result: OrchestratorResult,
) -> list[str]:
    names: list[str] = []
    seen: set[str] = set()
    for invocation in result.tool_invocations or ():
        if not isinstance(invocation, Mapping):
            continue
        tool_name = None
        for key in ("tool", "tool_name", "method", "name"):
            value = invocation.get(key)
            if isinstance(value, str) and value.strip():
                tool_name = value.strip()
                break
        if tool_name is None:
            continue
        lowered = tool_name.lower()
        if lowered in seen:
            continue
        seen.add(lowered)
        names.append(tool_name)
    return names


def _latest_workflow_execution_summary_from_result(
    result: OrchestratorResult,
) -> Mapping[str, Any]:
    for entry in reversed(tuple(result.aux_llm_calls or ())):
        if not isinstance(entry, Mapping):
            continue
        if entry.get("type") != "workflow_execution":
            continue
        summary = entry.get("execution_summary")
        if isinstance(summary, Mapping):
            return summary
    return {}


def _workflow_discovery_selection_learning_payload(
    workflow_discovery_result: Mapping[str, Any] | None,
) -> dict[str, Any]:
    discovery = (
        workflow_discovery_result
        if isinstance(workflow_discovery_result, Mapping)
        else {}
    )
    budget_exhausted = bool(discovery.get("budget_exhausted")) or (
        str(discovery.get("match_absence_reason") or "").strip().lower()
        == "workflow_discovery_budget_exhausted"
    )
    payload: dict[str, Any] = {
        "workflow_discovery_budget_exhausted": budget_exhausted,
        "workflow_discovery_match_absence_reason": (
            str(discovery.get("match_absence_reason") or "").strip() or None
        ),
        "workflow_discovery_budget_exhaustion_stage": (
            str(discovery.get("budget_exhaustion_stage") or "").strip() or None
        ),
        "workflow_discovery_budget_exhaustion_detail": (
            str(discovery.get("budget_exhaustion_detail") or "").strip() or None
        ),
        "workflow_discovery_candidate_count": _workflow_selection_outcome_safe_int(
            discovery.get("candidate_count")
        ),
        "workflow_discovery_match_count": _workflow_selection_outcome_safe_int(
            discovery.get("match_count")
        ),
    }
    timeout_budget = _workflow_selection_outcome_safe_float(
        discovery.get("timeout_budget_seconds")
    )
    if timeout_budget is not None:
        payload["workflow_discovery_timeout_budget_seconds"] = timeout_budget
    search_time_ms = _workflow_selection_outcome_safe_float(
        discovery.get("search_time_ms")
    )
    if search_time_ms is not None:
        payload["workflow_discovery_search_time_ms"] = search_time_ms
    return payload


def _workflow_required_evidence_selection_learning_payload(
    result: OrchestratorResult,
) -> dict[str, Any]:
    summary = _latest_workflow_execution_summary_from_result(result)
    required_tools = _workflow_required_tools_from_contract(
        summary.get("workflow_required_effects_contract")
        if isinstance(summary.get("workflow_required_effects_contract"), Mapping)
        else None
    )
    if not required_tools:
        raw_required_tools = summary.get("workflow_required_effects_required_tools")
        required_tools = [
            item.strip()
            for item in (raw_required_tools or ())
            if isinstance(item, str) and item.strip()
        ]
    tool_names = _workflow_selection_tool_invocation_names(result)
    executed_tool_names = {tool.lower() for tool in tool_names}
    missing_required_tools = [
        tool for tool in required_tools if tool.lower() not in executed_tool_names
    ]
    declared_count = _workflow_selection_outcome_safe_int(
        summary.get("workflow_required_effects_declared_count")
        or summary.get("required_effects_declared_count")
    )
    required_tool_count = len(required_tools)
    tool_invocation_count = len(tool_names)
    required_evidence_missing = bool(
        missing_required_tools
        or (
            declared_count > 0
            and required_tool_count > 0
            and tool_invocation_count == 0
        )
    )
    return {
        "workflow_required_effects_declared_count": declared_count,
        "workflow_required_effects_required_tools": required_tools,
        "workflow_required_effects_required_tool_count": required_tool_count,
        "tool_invocation_count": tool_invocation_count,
        "tool_invocation_names": tool_names,
        "required_evidence_tool_missing_count": len(missing_required_tools),
        "required_evidence_tool_missing_names": missing_required_tools,
        "required_evidence_missing": required_evidence_missing,
        "workflow_execution_action_success_count": _workflow_selection_outcome_safe_int(
            summary.get("action_success_count")
        ),
        "workflow_execution_action_started_count": _workflow_selection_outcome_safe_int(
            summary.get("action_started_count")
        ),
    }


def _selector_timeout_recovery_applied(
    selector_override_entry: Mapping[str, Any] | None,
) -> bool:
    return (
        isinstance(selector_override_entry, Mapping)
        and str(selector_override_entry.get("reason") or "").strip()
        == "selector_unmatched_candidate_budget_timeout_recovered_to_requested_workflow"
    )


def _workflow_terminal_success_evaluation_from_result(
    workflow_result: Any,
) -> Mapping[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None
    evaluation = result_data.get("workflow_terminal_success_evaluation")
    if isinstance(evaluation, Mapping):
        return evaluation
    return None


def _derive_workflow_terminal_status(workflow_result: Any) -> str | None:
    result_data = getattr(workflow_result, "data", None)
    if isinstance(result_data, Mapping):
        result_envelope = result_data.get(WORKFLOW_RESULT_ENVELOPE_KEY)
        if isinstance(result_envelope, Mapping):
            envelope_status = _workflow_execution_summary_text(
                result_envelope.get("terminal_status")
            )
            if envelope_status:
                return envelope_status
    error_text = _workflow_execution_summary_text(
        getattr(workflow_result, "error", None)
    )
    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    if not final_state:
        return None
    return derive_workflow_terminal_status(
        completed=bool(getattr(workflow_result, "completed", False)),
        final_state=final_state,
        error=error_text or None,
    )


def _workflow_result_effective_completed(workflow_result: Any) -> bool:
    if not bool(getattr(workflow_result, "completed", False)):
        return False
    if _workflow_execution_summary_text(getattr(workflow_result, "error", None)):
        return False
    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    if _workflow_final_state_is_failure_like(final_state):
        return False
    terminal_success_evaluation = _workflow_terminal_success_evaluation_from_result(
        workflow_result
    )
    if isinstance(terminal_success_evaluation, Mapping):
        return bool(terminal_success_evaluation.get("success"))
    return True


def _workflow_execution_summary_mapping_list(value: Any) -> list[Mapping[str, Any]]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
        return []
    return [
        cast(Mapping[str, Any], item) for item in value if isinstance(item, Mapping)
    ]


def _extract_workflow_step_failure_detail(envelope: Any) -> str | None:
    if not isinstance(envelope, Mapping):
        return None

    diagnostics = envelope.get("diagnostics")
    if isinstance(diagnostics, Mapping):
        error_text = _workflow_execution_summary_text(diagnostics.get("error"))
        if error_text:
            return error_text

    for key in ("error", "action_error"):
        error_text = _workflow_execution_summary_text(envelope.get(key))
        if error_text:
            return error_text

    output_payload = envelope.get("output_payload")
    if isinstance(output_payload, Mapping):
        for payload_key in ("result", "mcp_result"):
            payload = output_payload.get(payload_key)
            if not isinstance(payload, Mapping):
                continue
            error_text = _workflow_execution_summary_text(payload.get("error"))
            if error_text:
                return error_text
            message_text = _workflow_execution_summary_text(payload.get("message"))
            if message_text:
                return message_text

    return None


def _extract_explicit_workflow_failure_detail(workflow_result: Any) -> str | None:
    if _workflow_result_effective_completed(workflow_result):
        return None

    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None

    for key in (
        "last_action_error",
        "workflow_error",
        "failure_detail",
        "termination_detail",
        "error",
    ):
        error_text = _workflow_execution_summary_text(result_data.get(key))
        if error_text:
            return error_text

    last_step_envelope = result_data.get(LAST_WORKFLOW_STEP_RESULT_ENVELOPE_KEY)
    step_error = _extract_workflow_step_failure_detail(last_step_envelope)
    if step_error:
        return step_error

    step_envelopes = _workflow_execution_summary_mapping_list(
        result_data.get(WORKFLOW_STEP_RESULT_ENVELOPES_KEY)
    )
    for envelope in reversed(step_envelopes):
        step_error = _extract_workflow_step_failure_detail(envelope)
        if step_error:
            return step_error

    result_envelope = result_data.get(WORKFLOW_RESULT_ENVELOPE_KEY)
    if isinstance(result_envelope, Mapping):
        diagnostics = result_envelope.get("diagnostics")
        if isinstance(diagnostics, Mapping):
            error_text = _workflow_execution_summary_text(diagnostics.get("error"))
            if error_text:
                return error_text

    return None


def _workflow_error_text_looks_like_machine_reason(error_text: Any) -> bool:
    cleaned = _workflow_execution_summary_text(error_text)
    if not cleaned:
        return False
    if len(cleaned) > 120 or any(char.isspace() for char in cleaned):
        return False
    return bool(re.fullmatch(r"[#A-Za-z0-9_.:-]+", cleaned))


def _extract_operational_workflow_error_signal(workflow_result: Any) -> str | None:
    error_text = _workflow_execution_summary_text(
        getattr(workflow_result, "error", None)
    )
    if error_text:
        return error_text

    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None

    for key in ("last_action_error", "workflow_error", "error"):
        error_text = _workflow_execution_summary_text(result_data.get(key))
        if error_text:
            return error_text

    last_step_envelope = result_data.get(LAST_WORKFLOW_STEP_RESULT_ENVELOPE_KEY)
    step_error = _extract_workflow_step_failure_detail(last_step_envelope)
    if step_error:
        return step_error

    for envelope in _workflow_execution_summary_mapping_list(
        result_data.get(WORKFLOW_STEP_RESULT_ENVELOPES_KEY)
    ):
        step_error = _extract_workflow_step_failure_detail(envelope)
        if step_error:
            return step_error

    return None


def _workflow_result_contains_tool_progress(workflow_result: Any) -> bool:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return False

    for key in ("tool_invocations", "invocations", "tool_messages"):
        if _workflow_execution_summary_mapping_list(result_data.get(key)):
            return True

    extra_messages = _workflow_execution_summary_mapping_list(
        result_data.get("extra_messages")
    )
    return any(
        _workflow_execution_summary_text(message.get("role")) == "tool"
        for message in extra_messages
    )


def _should_continue_failed_custom_workflow_into_tool_pipeline(
    workflow_result: Any,
) -> bool:
    if _workflow_result_effective_completed(workflow_result):
        return False
    if _workflow_result_contains_tool_progress(workflow_result):
        return False

    operational_error = _extract_operational_workflow_error_signal(workflow_result)
    if operational_error and not _workflow_error_text_looks_like_machine_reason(
        operational_error
    ):
        return False
    return True


def _build_failed_custom_workflow_snapshot(
    *,
    workflow_id: str | None,
    workflow_result: Any,
) -> dict[str, Any] | None:
    cleaned_workflow_id = (
        workflow_id.strip()
        if isinstance(workflow_id, str) and workflow_id.strip()
        else None
    )
    if not cleaned_workflow_id or _workflow_result_effective_completed(workflow_result):
        return None

    snapshot: dict[str, Any] = {
        "workflow_id": cleaned_workflow_id,
        "completed": False,
        "tool_progress_detected": _workflow_result_contains_tool_progress(
            workflow_result
        ),
    }

    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    if final_state:
        snapshot["final_state"] = final_state

    operational_error = _extract_operational_workflow_error_signal(workflow_result)
    if operational_error:
        snapshot["operational_error"] = operational_error

    explicit_failure_detail = _extract_explicit_workflow_failure_detail(workflow_result)
    if explicit_failure_detail and explicit_failure_detail != operational_error:
        snapshot["failure_detail"] = explicit_failure_detail

    result_data = getattr(workflow_result, "data", None)
    if isinstance(result_data, Mapping):
        user_visible_failure_text = _workflow_execution_summary_text(
            result_data.get("response_text")
        ) or _workflow_execution_summary_text(result_data.get("summary"))
        if user_visible_failure_text:
            snapshot["user_visible_failure_text"] = user_visible_failure_text

    return snapshot


def _safe_workflow_execution_aux_snapshot_value(
    value: Any,
    *,
    depth: int = 0,
    max_depth: int = 3,
    max_items: int = 20,
) -> Any:
    if depth >= max_depth:
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        return str(type(value).__name__)
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    if isinstance(value, Mapping):
        snapshot: dict[str, Any] = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= max_items:
                break
            if not isinstance(key, str) or callable(item):
                continue
            snapshot[key] = _safe_workflow_execution_aux_snapshot_value(
                item,
                depth=depth + 1,
                max_depth=max_depth,
                max_items=max_items,
            )
        return snapshot
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        items: list[Any] = []
        for index, item in enumerate(value):
            if index >= max_items:
                break
            items.append(
                _safe_workflow_execution_aux_snapshot_value(
                    item,
                    depth=depth + 1,
                    max_depth=max_depth,
                    max_items=max_items,
                )
            )
        return items
    return str(value)


def _build_workflow_execution_aux_result_snapshot(
    workflow_result: Any,
) -> dict[str, Any] | None:
    result_data = getattr(workflow_result, "data", None)
    if not isinstance(result_data, Mapping):
        return None

    snapshot: dict[str, Any] = {}
    for key in _WORKFLOW_EXECUTION_AUX_RESULT_SNAPSHOT_KEYS:
        if key in result_data:
            raw_value = result_data.get(key)
        else:
            raw_value = None
            for (
                fallback_key
            ) in _WORKFLOW_EXECUTION_AUX_RESULT_SNAPSHOT_FALLBACK_KEYS.get(key, ()):
                if fallback_key in result_data:
                    raw_value = result_data.get(fallback_key)
                    break
            if raw_value is None:
                continue
        snapshot[key] = _safe_workflow_execution_aux_snapshot_value(raw_value)
    return snapshot or None


def _extract_workflow_execution_identifier_values(value: Any) -> list[str]:
    candidate_values: list[str] = []
    seen: set[str] = set()

    def _append(raw_value: Any) -> None:
        if len(candidate_values) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_IDS_PER_EFFECT:
            return
        cleaned = _workflow_execution_summary_text(raw_value)
        if not cleaned:
            return
        lowered = cleaned.lower()
        if lowered in seen:
            return
        seen.add(lowered)
        candidate_values.append(cleaned)

    if isinstance(value, str):
        _append(value)
        return candidate_values

    if isinstance(value, Mapping):
        for candidate_key in ("concept_id", "workflow_id", "id", "instance_id"):
            if candidate_key in value:
                _append(value.get(candidate_key))
        return candidate_values

    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        for item in value:
            if isinstance(item, Mapping):
                for candidate_key in ("concept_id", "workflow_id", "id", "instance_id"):
                    if candidate_key in item:
                        _append(item.get(candidate_key))
                        break
            else:
                _append(item)
        return candidate_values

    return candidate_values


def _normalise_workflow_mutation_kind(value: str) -> str:
    cleaned = str(value or "").strip().lower()
    if cleaned == "materialized":
        return "materialised"
    return cleaned


def _normalise_workflow_artefact_type(value: str) -> str:
    cleaned = str(value or "").strip().lower().strip("_")
    return re.sub(r"_+", "_", cleaned)


def _collect_workflow_durable_side_effects(
    payload: Any,
    *,
    path: tuple[str, ...] = (),
    depth: int = 0,
    collected: list[dict[str, Any]] | None = None,
    seen: set[tuple[str, str, str, tuple[str, ...]]] | None = None,
) -> list[dict[str, Any]]:
    if collected is None:
        collected = []
    if seen is None:
        seen = set()
    if (
        not isinstance(payload, Mapping)
        or depth > _WORKFLOW_EXECUTION_SUMMARY_MAX_SCAN_DEPTH
    ):
        return collected

    for key, value in payload.items():
        if len(collected) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_SIDE_EFFECTS:
            break
        if not isinstance(key, str):
            continue
        key_text = key.strip()
        if not key_text:
            continue
        lowered_key = key_text.lower()
        if lowered_key in _WORKFLOW_EXECUTION_SUMMARY_IGNORED_KEYS:
            continue

        match = _WORKFLOW_MUTATION_ID_FIELD_PATTERN.match(lowered_key)
        if match:
            artefact_ids = _extract_workflow_execution_identifier_values(value)
            if artefact_ids:
                mutation_kind = _normalise_workflow_mutation_kind(match.group(1))
                artefact_type = _normalise_workflow_artefact_type(match.group(2))
                source_path = ".".join((*path, key_text))
                fingerprint = (
                    mutation_kind,
                    artefact_type,
                    source_path,
                    tuple(artefact_ids),
                )
                if fingerprint not in seen:
                    seen.add(fingerprint)
                    collected.append(
                        {
                            "mutation_kind": mutation_kind,
                            "artefact_type": artefact_type,
                            "source_key": key_text,
                            "source_path": source_path,
                            "artefact_count": len(artefact_ids),
                            "artefact_ids": artefact_ids,
                        }
                    )
            continue

        if isinstance(value, Mapping):
            _collect_workflow_durable_side_effects(
                value,
                path=(*path, key_text),
                depth=depth + 1,
                collected=collected,
                seen=seen,
            )
            continue

        if isinstance(value, Sequence) and not isinstance(
            value, (str, bytes, bytearray)
        ):
            for index, item in enumerate(value):
                if len(collected) >= _WORKFLOW_EXECUTION_SUMMARY_MAX_SIDE_EFFECTS:
                    break
                if not isinstance(item, Mapping):
                    continue
                _collect_workflow_durable_side_effects(
                    item,
                    path=(*path, f"{key_text}[{index}]"),
                    depth=depth + 1,
                    collected=collected,
                    seen=seen,
                )

    return collected


def _build_workflow_execution_summary(
    *,
    workflow_id: str,
    workflow_result: Any,
) -> dict[str, Any]:
    result_data = getattr(workflow_result, "data", None)
    workflow_data: Mapping[str, Any] = (
        result_data if isinstance(result_data, Mapping) else {}
    )

    step_envelopes = _workflow_execution_summary_mapping_list(
        workflow_data.get(WORKFLOW_STEP_RESULT_ENVELOPES_KEY)
    )
    success_count = 0
    failure_count = 0
    unknown_count = 0
    first_failing_state_id: str | None = None
    first_failing_action_id: str | None = None
    for envelope in step_envelopes:
        action_outcome = _workflow_execution_summary_text(
            envelope.get("action_outcome")
        ) or _workflow_execution_summary_text(envelope.get("action_status"))
        lowered_outcome = (action_outcome or "").lower()
        if lowered_outcome == "success":
            success_count += 1
        elif lowered_outcome in {"failed", "failure"}:
            failure_count += 1
            if first_failing_state_id is None:
                first_failing_state_id = _workflow_execution_summary_text(
                    envelope.get("state_id")
                )
            if first_failing_action_id is None:
                first_failing_action_id = _workflow_execution_summary_text(
                    envelope.get("action_id")
                )
        else:
            unknown_count += 1

    launch_resolution = workflow_data.get("workflow_launch_input_resolution")
    if isinstance(launch_resolution, Mapping):
        if first_failing_state_id is None:
            first_failing_state_id = _workflow_execution_summary_text(
                launch_resolution.get("failing_state_id")
            )
        if first_failing_action_id is None:
            first_failing_action_id = _workflow_execution_summary_text(
                launch_resolution.get("failing_action_id")
            )

    terminal_effect_events = _workflow_execution_summary_mapping_list(
        workflow_data.get(WORKFLOW_TERMINAL_EFFECT_EVENTS_KEY)
    )
    terminal_effects: list[dict[str, Any]] = []
    for event in terminal_effect_events[
        :_WORKFLOW_EXECUTION_SUMMARY_MAX_TERMINAL_EFFECTS
    ]:
        terminal_effects.append(
            {
                "state_id": _workflow_execution_summary_text(event.get("state_id")),
                "symbol": _workflow_execution_summary_text(event.get("symbol")),
                "alias": _workflow_execution_summary_text(event.get("alias")),
                "applied": bool(event.get("applied")),
            }
        )

    runtime_event_count = len(
        _workflow_execution_summary_mapping_list(
            workflow_data.get(WORKFLOW_RUNTIME_EVENTS_KEY)
        )
    )
    durable_side_effects = _collect_workflow_durable_side_effects(workflow_data)
    durable_side_effect_count = sum(
        int(entry.get("artefact_count") or 0) for entry in durable_side_effects
    )

    final_state = _workflow_execution_summary_text(
        getattr(workflow_result, "final_state", None)
    )
    reported_completed = bool(getattr(workflow_result, "completed", False))
    effective_completed = _workflow_result_effective_completed(workflow_result)
    terminal_status = _derive_workflow_terminal_status(workflow_result)
    completion_gate_summary = _workflow_completion_gate_summary(workflow_result)
    terminal_success_contract = _workflow_terminal_success_contract_from_result(
        workflow_result
    )
    terminal_success_evaluation = _workflow_terminal_success_evaluation_from_result(
        workflow_result
    )
    workflow_required_effects_contract = (
        _workflow_required_effects_contract_from_result(workflow_result)
    )
    workflow_required_effects_contract_source = (
        _workflow_required_effects_contract_source_from_result(workflow_result)
    )
    workflow_required_effects_required_tools = _workflow_required_tools_from_contract(
        workflow_required_effects_contract
    )

    summary: dict[str, Any] = {
        "schema_version": _WORKFLOW_EXECUTION_SUMMARY_SCHEMA_VERSION,
        "workflow_id": workflow_id,
        # `completed` is the verdict callers should trust; preserve the raw executor
        # flag separately because some workflows historically reported `completed=True`
        # even when their terminal state or error made the outcome failure-like.
        "completed": effective_completed,
        "effective_completed": effective_completed,
        "reported_completed": reported_completed,
        "terminal_status": terminal_status,
        "final_state": final_state,
        "step_result_envelope_count": len(step_envelopes),
        "action_started_count": len(step_envelopes),
        "action_completed_count": len(step_envelopes),
        "action_success_count": success_count,
        "action_failure_count": failure_count,
        "action_unknown_count": unknown_count,
        "first_failing_state_id": first_failing_state_id,
        "first_failing_action_id": first_failing_action_id,
        "runtime_event_count": runtime_event_count,
        "terminal_effect_count": len(terminal_effect_events),
        "terminal_effects": terminal_effects,
        "durable_side_effect_count": durable_side_effect_count,
        "durable_side_effects": durable_side_effects,
    }
    if isinstance(completion_gate_summary, Mapping):
        summary["completion_gate_safe_to_claim_completion"] = bool(
            completion_gate_summary.get("safe_to_claim_completion", False)
        )
        summary["completion_gate_blocking_reason_codes"] = list(
            completion_gate_summary.get("blocking_reason_codes") or []
        )
    if isinstance(terminal_success_contract, Mapping):
        summary["terminal_success_contract"] = dict(terminal_success_contract)
    if isinstance(terminal_success_evaluation, Mapping):
        summary["terminal_success_evaluation"] = dict(terminal_success_evaluation)
    if isinstance(workflow_required_effects_contract, Mapping):
        summary["workflow_required_effects_contract_id"] = (
            _workflow_execution_summary_text(
                workflow_required_effects_contract.get("contract_id")
            )
        )
        summary["workflow_required_effects_declared_count"] = len(
            workflow_required_effects_contract.get("required_effects") or []
        )
        summary["workflow_required_effects_required_tools"] = list(
            workflow_required_effects_required_tools
        )
        summary["workflow_required_effects_required_tool_count"] = len(
            workflow_required_effects_required_tools
        )
        if workflow_required_effects_contract_source:
            summary["workflow_required_effects_contract_source"] = (
                workflow_required_effects_contract_source
            )
    return summary


def _build_workflow_execution_aux_entry(
    *,
    workflow_id: str,
    workflow_result: Any,
) -> dict[str, Any]:
    result_data = getattr(workflow_result, "data", None)
    execution_summary = (
        result_data.get("workflow_execution_summary")
        if isinstance(result_data, Mapping)
        else None
    )
    if not isinstance(execution_summary, Mapping):
        execution_summary = _build_workflow_execution_summary(
            workflow_id=workflow_id,
            workflow_result=workflow_result,
        )

    payload = {
        "type": "workflow_execution",
        "workflow_id": workflow_id,
        "final_state": _workflow_execution_summary_text(
            getattr(workflow_result, "final_state", None)
        ),
        "completed": _workflow_result_effective_completed(workflow_result),
        "execution_summary": dict(execution_summary),
    }
    result_snapshot = _build_workflow_execution_aux_result_snapshot(workflow_result)
    if isinstance(result_snapshot, Mapping):
        payload["result_snapshot"] = dict(result_snapshot)
    return payload


def _derive_workflow_selection_rationale(
    *,
    selected_workflow_id: str | None,
    selector_verdict: str | None,
    selector_source: str | None,
    candidate_workflow_ids: Sequence[str],
    explicit_reasoning: str | None = None,
) -> str:
    """Return a stable machine-readable workflow-selection rationale code."""

    explicit = str(explicit_reasoning or "").strip()
    source = (selector_source or "default").strip().lower() or "default"
    selected = (selected_workflow_id or "").strip()
    verdict = (selector_verdict or "").strip()
    candidate_set = {
        str(item).strip().lower()
        for item in candidate_workflow_ids
        if isinstance(item, str) and str(item).strip()
    }

    if source == "selector_override":
        if explicit:
            return f"selector_override:{explicit}"
        if verdict:
            return f"selector_override_verdict:{verdict}"
        return "selector_override"
    if source == "selector":
        if selected and selected.lower() in candidate_set:
            return "selector_selected_discovered_candidate"
        if verdict:
            return f"selector_verdict:{verdict}"
        return "selector_route_without_explicit_verdict"
    if source == "presenter_mode":
        return "presenter_mode_route"
    if source == "default":
        if explicit:
            return f"default_reason:{explicit}"
        return "default_routing_fallback"
    if explicit:
        return f"routing_source:{source}:{explicit}"
    return f"routing_source:{source}"


def _derive_selected_workflow_goal_label(
    *,
    selected_workflow_id: str | None,
    selected_workflow_name: str | None = None,
) -> str | None:
    workflow_name = (
        selected_workflow_name.strip()
        if isinstance(selected_workflow_name, str) and selected_workflow_name.strip()
        else None
    )
    if workflow_name:
        return f"Execute {workflow_name}."
    workflow_id = (
        selected_workflow_id.strip()
        if isinstance(selected_workflow_id, str) and selected_workflow_id.strip()
        else None
    )
    if workflow_id:
        return f"Execute {workflow_id}."
    return None


def _build_selector_safe_general_fallback_payload(
    *,
    selected_workflow_id: str | None,
    selector_verdict: str | None,
    selection_metadata: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Return bounded fallback metadata when selector intent was non-generic.

    The selector may name a concrete non-default workflow that is not actually
    eligible for selection from the current candidate set. Python should not
    reinterpret that as an affirmative choice of the generic chat workflow.
    Instead, preserve the non-default intent and hand off to the safe general
    tool workflow.
    """

    selected_workflow_id_text = (
        str(selected_workflow_id).strip()
        if isinstance(selected_workflow_id, str) and str(selected_workflow_id).strip()
        else None
    )
    if selected_workflow_id_text != CHAT_ASSISTANT_WORKFLOW_ID:
        return None

    selector_verdict_text = (
        str(selector_verdict).strip().lower()
        if isinstance(selector_verdict, str) and str(selector_verdict).strip()
        else ""
    )
    if selector_verdict_text != "rag_default":
        return None

    metadata = (
        {
            str(key): value
            for key, value in selection_metadata.items()
            if isinstance(key, str)
        }
        if isinstance(selection_metadata, Mapping)
        else {}
    )
    selection_resolution = (
        str(metadata.get("selection_resolution") or "").strip().lower()
    )
    if selection_resolution != "default_workflow_fallback_unmatched_candidate":
        return None

    requested_candidate_workflow_id = (
        str(
            metadata.get("unmatched_candidate_workflow_id")
            or metadata.get("requested_candidate_workflow_id")
            or ""
        ).strip()
        or None
    )
    if not requested_candidate_workflow_id:
        return None
    if requested_candidate_workflow_id in {
        CHAT_ASSISTANT_WORKFLOW_ID,
        CHAT_NARRATION_WORKFLOW_ID,
        TOOL_CALLING_WORKFLOW_ID,
    }:
        return None

    return {
        "requested_candidate_workflow_id": requested_candidate_workflow_id,
        "selection_resolution": selection_resolution,
        "raw_candidate_label": (
            str(metadata.get("raw_candidate_label") or "").strip() or None
        ),
    }


def _normalise_selector_candidate_role(candidate: Mapping[str, Any]) -> str | None:
    raw_role = candidate.get("routing_profile_role")
    if isinstance(raw_role, str) and raw_role.strip():
        return raw_role.strip().lower()
    routing_profile = candidate.get("routing_profile")
    if isinstance(routing_profile, Mapping):
        nested_role = routing_profile.get("role")
        if isinstance(nested_role, str) and nested_role.strip():
            return nested_role.strip().lower()
    return None


def _build_selector_single_discovered_execution_recovery_payload(
    *,
    selected_workflow_id: str | None,
    selector_verdict: str | None,
    selection_metadata: Mapping[str, Any] | None,
    discovered_matches: Sequence[Mapping[str, Any]],
) -> dict[str, Any] | None:
    """Recover a selector default when one specialised execution candidate remains."""

    selected_workflow_id_text = (
        str(selected_workflow_id).strip()
        if isinstance(selected_workflow_id, str) and str(selected_workflow_id).strip()
        else None
    )
    if selected_workflow_id_text != CHAT_ASSISTANT_WORKFLOW_ID:
        return None

    selector_verdict_text = (
        str(selector_verdict).strip().lower()
        if isinstance(selector_verdict, str) and str(selector_verdict).strip()
        else ""
    )
    if selector_verdict_text != "rag_default":
        return None

    metadata = (
        {
            str(key): value
            for key, value in selection_metadata.items()
            if isinstance(key, str)
        }
        if isinstance(selection_metadata, Mapping)
        else {}
    )
    selection_resolution = (
        str(metadata.get("selection_resolution") or "").strip().lower()
    )
    if selection_resolution != "default_workflow_fallback":
        return None

    eligible_specialised_candidates: list[dict[str, Any]] = []
    for candidate in discovered_matches:
        if not isinstance(candidate, Mapping):
            continue
        concept_id = str(candidate.get("concept_id") or "").strip()
        if not concept_id or concept_id in _SELECTOR_GENERIC_WORKFLOW_IDS:
            continue
        if candidate.get("routing_eligible") is False:
            continue
        if candidate.get("is_executable") is False:
            continue
        if candidate.get("is_policy_safe") is False:
            continue
        if candidate.get("turn_launchable") is False:
            continue
        candidate_role = _normalise_selector_candidate_role(candidate)
        if candidate_role not in {None, "", "execution"}:
            continue
        eligible_specialised_candidates.append(
            {
                "workflow_id": concept_id,
                "name": str(candidate.get("name") or "").strip() or concept_id,
                "role": candidate_role or "execution",
            }
        )

    if len(eligible_specialised_candidates) != 1:
        return None

    recovered_candidate = eligible_specialised_candidates[0]
    return {
        "recovered_candidate_workflow_id": recovered_candidate["workflow_id"],
        "recovered_candidate_name": recovered_candidate["name"],
        "recovered_candidate_role": recovered_candidate["role"],
        "eligible_specialised_candidate_ids": [
            candidate["workflow_id"] for candidate in eligible_specialised_candidates
        ],
        "selection_resolution": selection_resolution,
        "raw_candidate_label": (
            str(metadata.get("raw_candidate_label") or "").strip() or None
        ),
    }


def _describe_tool_pipeline_override_reason(reason: str) -> str:
    clean_reason = str(reason or "").strip()
    if clean_reason == "selector_unmatched_candidate_requires_safe_general_fallback":
        return (
            "Selector proposed a concrete non-default workflow that was not "
            "eligible from the current candidate set, so the safe general tool "
            "workflow was selected instead."
        )
    if (
        clean_reason
        == "selected_custom_workflow_launchability_requires_safe_general_fallback"
    ):
        return (
            "The selected specialised workflow could not launch from the current "
            "turn inputs, so the safe general tool workflow was selected instead."
        )
    if (
        clean_reason
        == "selected_custom_workflow_cannot_satisfy_multi_surface_turn_contract"
    ):
        return (
            "The selected specialised workflow did not advertise tool-pipeline "
            "execution, but the turn contract required evidence from multiple "
            "surfaces including external ones, so the safe general tool workflow "
            "was selected instead."
        )
    return clean_reason or "Safe general tool workflow selected by override."


@dataclass(frozen=True)
class _WorkflowModelPolicyState:
    enabled: bool
    policy: Mapping[str, Any] | None
    policy_id: str | None
    predicate_id: str | None
    errors: Sequence[str]


