class _ModelCandidate:
    provider: str | None
    model: str | None
    raw: str
    source: str
    host: str | None = None


@dataclass(frozen=True)
class _StructuredToolCandidateResolution:
    """Resolved structured-tool candidate set for one LLM planning call."""

    tool_definitions: tuple[ToolDefinition, ...]
    candidate_tool_names: tuple[str, ...]
    excluded_tools: tuple[Mapping[str, Any], ...]
    required_tools: tuple[str, ...]
    hinted_families: tuple[str, ...]
    workflow_step_id: str
    workflow_step_profile: str
    effective_cap: int
    provider_limit: int
    cap_applied: bool
    truncation_applied: bool
    write_policy_reason: str
    warnings: tuple[str, ...]


@dataclass(frozen=True)
class _ResolvedWritePolicyDecision:
    allowed_tools: frozenset[str]
    reason: str
    decision_basis: str
    outcome: str
    user_denial_detected: bool
    risk_classes: Mapping[str, str]
    tool_outcomes: Mapping[str, str]
